import * as E from './engine.js';
import * as S from './simulator.js';
import {CLASSIC,COLORS,clone,validateRules,setPath} from './rules.js';
import {drawVoyages,progress} from './voyages.js';
import {playableMap} from './europe-map.js';
import {artFor} from './tile-art.js';
import {MAP_WIDTH,MAP_HEIGHT} from './europe.js';
import {cardById} from './cards.js';
const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,action,cls='',disabled=false)=>`<button class="${cls}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`;
const equipmentIcons={tente:'⛺',rechaud:'🍳',chambre:'🛞',kit:'🧰',gps:'🧭',duvet:'🛏️',secours:'🩹',sacoches:'🎒'};
let m=null,screen='home',modal='',mode='plateau',roster=[{name:'Joueur 1',bike:'gravel'}],choosing=0,drawn=[],setupRules=clone(CLASSIC),draft=null,message='',zoom=1,selected=0,mapSelection='',route=[],cardIndex=-1,ferryTarget='',auto=localStorage.getItem('velo-auto')!=='false',profiles={};
try{profiles=JSON.parse(localStorage.getItem('velo-rule-profiles'))||{};}catch{}
try{const raw=localStorage.getItem('velo-save');if(raw){const saved=JSON.parse(raw);if(saved.version===1)localStorage.setItem('velo-save-before-multiplayer',raw);if(saved.mode==='plateau'&&saved.mapVersion<7)localStorage.setItem('velo-save-before-new-map',raw);m=S.load(raw);}}catch{message='Sauvegarde illisible : le fichier existant reste conservé.';}
function persist(force=false){if(m&&(auto||force))try{localStorage.setItem('velo-save',S.serialize(m));return true;}catch{message='Stockage indisponible : utilise Exporter la partie.';return false;}}
function render(){const scroll=document.querySelector('.map'),sx=scroll?.scrollLeft,sy=scroll?.scrollTop;app.innerHTML=`<header><b>🚲 L’Aventure à Vélo</b><nav>${btn('⚙️ Règles','rules','light')}${btn('Paramètres','settings','light')}${screen==='game'?btn('Accueil','home','light'):''}</nav></header>`+(screen==='game'&&m?game():screen==='voyages'?choices():screen==='equipment'?equipmentSetup():screen==='setup'?setup():screen==='modes'?modes():home())+overlay();bind();if(scroll){const map=document.querySelector('.map');if(map){map.scrollLeft=sx;map.scrollTop=sy;}}persist();}
function home(){return `<main class="home"><section><span class="eyebrow">SIMULATEUR DE JEU DE SOCIÉTÉ</span><h1>L’Europe,<br>à votre rythme.</h1><p class="sub">1 à 6 joueurs, un plateau commun. Un tour = une journée : jusqu’à 5 cases, ou une journée de travail ou de repos.</p>${btn('Nouvelle aventure →','new')}${m?btn('Reprendre','continue','light'):''}<p class="toast" role="status">${esc(message)}</p><p class="footer">SANS DÉS · RÈGLES MODIFIABLES · SAUVEGARDE LOCALE</p></section><div class="hero"><span>🚴</span></div></main>`;}
function modes(){return `<main class="voyage-selection"><h1>Choisir votre plateau</h1><div class="mode-choices">${[['plateau','assets/europe/nouvelle-carte.png','🗺 Plateau Europe','Nouvelle carte : hexagones égaux, moyenne montagne et bateaux.'],['tuiles','assets/tiles/plaine-0.webp','🧩 Tuiles','Construisez ensemble le réseau avec les 48 tuiles illustrées.']].map(([id,img,title,text])=>`<button class="mode-card" data-mode="${id}"><img src="${img}" alt="${title}"/><div><h3>${title}</h3><p>${text}</p></div></button>`).join('')}</div>${btn('Retour','home','light')}</main>`;}
 function setup(){return `<main class="voyage-selection"><span class="eyebrow">${mode==='plateau'?'PLATEAU EUROPE':'TUILES'}</span><h1>Autour de la table</h1><label>Nombre de joueurs <select id="player-count">${Array.from({length:6},(_,i)=>`<option value="${i+1}" ${roster.length===i+1?'selected':''}>${i+1}</option>`).join('')}</select></label><div class="roster">${roster.map((p,i)=>`<article class="panel"><h3 style="color:${COLORS[i]}">● Joueur ${i+1}</h3><label>Nom <input data-roster="${i}" data-field="name" value="${esc(p.name)}" maxlength="40"/></label><label>Vélo <select data-roster="${i}" data-field="bike">${Object.entries(setupRules.bikes).map(([id,b])=>`<option value="${id}" ${p.bike===id?'selected':''}>${b.name} · ${b.capacity} emplacements</option>`).join('')}</select></label></article>`).join('')}</div><p>Après le vélo, chacun achète son matériel, puis choisit son objectif Voyage. Règles : ${esc(setupRules.name)} · ${setupRules.distance} cases/jour · ${setupRules.startEnergy} énergie · ${setupRules.startMoney} pièces.</p>${btn('Acheter le matériel →','start')}${btn('Changer le plateau','modes','light')}</main>`;}
function equipmentSetup(){
 const p=roster[choosing],bike=setupRules.bikes[p.bike],items=p.items||[];
 const spent=items.reduce((n,id)=>n+setupRules.equipment[id].price,0),space=items.reduce((n,id)=>n+setupRules.equipment[id].space,0);
 const descriptions={tente:'Permet le bivouac',rechaud:'Permet de manger hors ville ou auberge',chambre:'Pièce de rechange pour le vélo',kit:'Répare les crevaisons',gps:'Aide à s’orienter',duvet:'Améliore le repos',secours:'Soigne les blessures',sacoches:'Offre des provisions'};
 return `<main class="voyage-selection"><span class="eyebrow">MATÉRIEL · ${choosing+1}/${roster.length}</span><h1>${esc(p.name)}, équipe ton vélo.</h1><p>${esc(bike.name)} · ${space}/${bike.capacity} emplacements · ${setupRules.startMoney-spent} pièce(s) restantes.</p><div class="equipment-grid">${Object.entries(setupRules.equipment).map(([id,e])=>`<button class="equipment-choice ${items.includes(id)?'owned':''}" data-equipment="${id}" aria-pressed="${items.includes(id)}" ${!items.includes(id)&&(spent+e.price>setupRules.startMoney||space+e.space>bike.capacity)?'disabled':''}><span class="equipment-head"><span class="equipment-icon" aria-hidden="true">${equipmentIcons[id]}</span><strong>${esc(e.name)}</strong></span><span class="equipment-meta">${e.price} pièce${e.price>1?'s':''} · ${e.space} emplacement${e.space>1?'s':''}</span><small>${descriptions[id]}</small><span class="equipment-status">${items.includes(id)?'✓ Dans le vélo':'Cliquer pour ajouter'}</span></button>`).join('')}</div><p>Tu pourras aussi acheter d’autres objets en ville pendant la partie.</p>${btn(choosing<roster.length-1?'Équiper le joueur suivant →':'Choisir les voyages →','equipment-next')}${btn('Retour aux vélos','setup','light')}</main>`;
}
function artwork(v,full=false){return `<div class="voyage-art ${full?'full-card ':''}art-${v.id}" role="img" aria-label="${esc(v.title)}"></div>`;}
function choices(){return `<main class="voyage-selection"><span class="eyebrow">OBJECTIF PERSONNEL · ${choosing+1}/${roster.length}</span><h1>${esc(roster[choosing].name)}, choisis ton voyage.</h1><p>Chaque joueur possède ses ressources et son objectif.</p><div class="voyage-grid">${drawn.map(v=>`<article class="voyage-choice" style="--voyage-color:${v.color}">${artwork(v,true)}<div class="voyage-body"><h2>${v.title}</h2><p>${v.from} → ${v.to}</p><button data-voyage="${v.id}">Choisir ${v.title} →</button></div></article>`).join('')}</div></main>`;}
function objective(g){const p=progress(g);return p?`<section class="objective" style="--voyage-color:${p.v.color}">${artwork(p.v)}<div class="objective-title"><span class="eyebrow">CARTE VOYAGE · ${esc(g.name)}</span><h3>${p.v.title}</h3><strong>${p.v.from} → ${p.v.to}</strong><small>${g.completed?'✓ Objectif accompli':p.ready?'Rejoins '+p.v.to:'Remplis les étapes puis rejoins '+p.v.to}</small></div><div class="objective-checks">${p.rows.map(r=>`<div class="${r.done?'checked':''}">${r.done?'✓':'○'} ${r.label} <b>${r.value}/${r.target}</b></div>`).join('')}</div></section>`:'';}
function tile(t){const a=artFor(t),c=E.terrains[t.type];return a?`<img class="tile-art" src="${a.src}" alt="${c.name}" draggable="false" style="transform:rotate(${a.rotation*90}deg)"/>`:`<svg viewBox="0 0 100 100"><rect width="100" height="100" fill="${c.color}"/>${E.roads(t).map(d=>`<path d="M50 50 L${[[50,0],[100,50],[50,100],[0,50]][d].join(' ')}" stroke="#fff1ce" stroke-width="10"/>`).join('')}</svg>`;}
function tileMap(g,reachable){S.rescueHand(m);const tiles=Object.values(g.board),spots=g.phase==='place'&&m.hand[selected]?E.spots(g,m.hand[selected]):[],all=[...tiles,...spots],minX=Math.min(...all.map(t=>t.x))-1,minY=Math.min(...all.map(t=>t.y))-1,maxX=Math.max(...all.map(t=>t.x))+1,maxY=Math.max(...all.map(t=>t.y))+1,size=132*zoom;return `<div class="world" style="width:${(maxX-minX+1)*size}px;height:${(maxY-minY+1)*size}px">${tiles.map(t=>{const k=E.key(t.x,t.y);return `<div class="tile ${reachable.some(n=>n.x===t.x&&n.y===t.y)?'reachable':''}" data-move="${k}" role="button" tabindex="0" aria-label="${esc(t.name||E.terrains[t.type].name)} · ${S.cost(m,t)} énergie" style="left:${(t.x-minX)*size}px;top:${(t.y-minY)*size}px;width:${size}px;height:${size}px">${tile(t)}<label>${esc(t.name||E.terrains[t.type].name)}</label><div class="tile-tokens">${m.players.filter(p=>p.pos===k).map(p=>`<span data-token="${p.id}" title="${esc(p.name)}" style="background:${p.color}">${p.id.slice(1)}</span>`).join('')}</div></div>`;}).join('')}${spots.map(t=>`<button class="spot" data-place="${t.x},${t.y}" aria-label="Poser en ${t.x},${t.y}" style="left:${(t.x-minX)*size}px;top:${(t.y-minY)*size}px;width:${size}px;height:${size}px">+</button>`).join('')}</div>`;}
function game(){const p=S.player(m),g=S.view(m),reachable=S.moves(m),r=m.rules,scale=.8*zoom;return `<main class="game"><div class="player-order" aria-label="Ordre des joueurs">${m.players.map((p,i)=>`<button data-player="${i}" class="${i===m.activeIndex?'active':''}" style="--player-color:${p.color}"><span>●</span> ${esc(p.name)} · ${p.points} ✨ <small>Jour ${p.availableDay}${i===m.activeIndex?' · joue maintenant':''}</small></button>`).join('')}</div><div class="topbar"><div><span class="eyebrow">${m.mode==='plateau'?'PLATEAU EUROPE':'TUILES'} · JOUR ${m.round}</span><h2>${esc(p.name)} <small class="muted">${m.moved}/${S.distance(m)} cases aujourd’hui</small></h2></div><div class="stats">${[['⚡','Énergie',p.energy+'/'+r.maxEnergy],['🍎','Nourriture',p.food],['🪙','Argent',p.money],['✨','Aventure',p.points]].map(([i,n,v])=>`<div class="stat">${i} ${n}<strong>${v}</strong></div>`).join('')}</div></div><div class="hint">${m.done?'Partie terminée.':m.phase==='event'?'Résous la carte pour passer au joueur suivant.':m.phase==='place'?'Pose une tuile, ou consacre cette journée au travail / repos.':m.moved>=S.distance(m)?'Limite atteinte. Termine ta journée pour tirer une carte.':'Itinéraire libre : jusqu’à '+S.distance(m)+' cases aujourd’hui. Travail et hébergement occupent une journée sans rouler.'}</div>${objective(g)}<div class="layout"><section><div class="map-wrap"><div class="map">${m.mode==='plateau'?`<div class="europe-world" style="width:${1536*scale}px;height:${1024*scale}px">${playableMap(g,reachable,(_,t)=>S.cost(m,t),mapSelection)}</div>`:tileMap(g,reachable)}</div><div class="maptools">${btn('−','zoomout')}${btn('+','zoomin')}${btn('◎','center')}</div></div>${m.mode==='tuiles'?`<div class="hand">${m.hand.map((t,i)=>`<button data-select="${i}" class="${i===selected?'active':''}" ${m.phase!=='place'?'disabled':''}>${tile(t)}<small>${E.terrains[t.type].name}</small></button>`).join('')}${btn('↻ Tourner','rotate','light',m.phase!=='place')}</div>`:''}${details(reachable)}<div class="board-legend">${['plaine','montagne','ville','cote'].map(id=>`<span>${E.terrains[id].icon} ${E.terrains[id].name} : ${r.terrain[id]} ⚡</span>`).join('')}<span>🚩 Départ · 🏁 Arrivée du joueur actif</span></div><div class="toast" role="status">${esc(message)}</div>${leaderboard()}</section>${sidebar()}</div></main>`;}
function details(reachable){const t=m.board[mapSelection];if(!t)return '<div class="cell-details placeholder">Clique sur une case pour consulter son coût puis choisir le déplacement.</div>';const cost=S.cost(m,t),p=S.player(m),neighbor=reachable.some(n=>m.mode==='plateau'?n.key===mapSelection:E.key(n.x,n.y)===mapSelection),allowed=neighbor&&p.energy>=cost;const status=m.done?'Partie terminée.':m.phase==='event'?'Résous la carte.':m.phase==='place'?'Pose d’abord une tuile.':m.moved>=S.distance(m)?'Maximum de cases atteint pour cette journée.':!neighbor?'Choisis une case voisine accessible.':p.energy<cost?'Énergie insuffisante.':'Case accessible.';return `<div class="cell-details"><div><strong>${E.terrains[t.type].icon} ${esc(t.name||E.terrains[t.type].name)}</strong><small>${cost} énergie · ${status}</small></div>${btn('🚴 Rouler ici','move','',!allowed)}</div>`;}
function sidebar(){const p=S.player(m),r=m.rules,blocked=m.done||m.phase==='event',dayBlocked=blocked||m.moved>0||m.placed,city=m.board[p.pos].type==='ville';return `<aside class="panel"><h3>La journée de ${esc(p.name)}</h3><p>${esc(r.bikes[p.bike].name)} · inventaire ${S.inventorySpace(m)}/${r.bikes[p.bike].capacity}</p><div class="actions">${btn('🍎 Manger · +'+(r.food.energy+(p.items.includes('rechaud')?r.food.stoveBonus:0))+' énergie','eat','',blocked||!p.food||m.ate>=r.food.maxPerTurn||p.energy>=r.maxEnergy)}${btn('🥕 Acheter '+r.food.quantity+' provisions · '+r.food.price+' pièces','food','',blocked||p.money<r.food.price||(r.food.cityOnly&&!city))}${btn('🍽 Restaurant · '+r.food.restaurantPrice+' pièces · +'+r.food.restaurantEnergy+' énergie','restaurant','',blocked||!city||p.money<r.food.restaurantPrice||p.energy>=r.maxEnergy||m.ate>=r.food.maxPerTurn)}${btn('🔧 Travailler · +'+r.salary+' pièces · '+r.workDays+' jour(s)','work','',dayBlocked||(r.workCityOnly&&!city))}${Object.entries(r.rest).map(([id,a])=>btn(`${id==='bivouac'?'⛺':id==='camping'?'🏕':'🏨'} ${a.name} · ${a.price} pièces · +${a.energy} énergie · ${a.days} jour(s)`,'rest-'+id,'',dayBlocked||p.money<a.price||(a.tent&&!p.items.includes('tente'))||(a.cityOnly&&!city))).join('')}${btn('🎒 Équipements','shop','',blocked)}${btn('Terminer ma journée →','endturn','',blocked)}${btn('Sauvegarder','save','light')}${btn('Historique et statistiques','stats','light')}${btn('Terminer la partie','finish','light')}</div><p class="muted">Travail et repos : avant tout déplacement ou pose de tuile. Bivouac : tente requise si activée dans les règles.</p><h4>Inventaire personnel</h4><p>${p.items.map(i=>esc(r.equipment[i].name)).join(' · ')||'Aucun équipement'}</p><h4>Journal personnel</h4><div class="log">${p.log.map(l=>`<div>• ${esc(l)}</div>`).join('')}</div></aside>`;}
function leaderboard(){return `<section class="panel standings"><h3>Classement</h3><ol>${S.ranking(m).map(p=>`<li><span style="color:${p.color}">●</span> ${esc(p.name)} <b>${p.points} points Aventure</b> · ${p.completed?'✓ Objectif accompli':'Objectif en cours'}</li>`).join('')}</ol><p class="muted">Victoire : ${m.rules.victory.mode==='points'?m.rules.victory.points+' points':m.rules.victory.mode==='turns'?m.rules.victory.turns+' jours':m.rules.victory.allObjectives?'tous les objectifs':'premier objectif accompli'}. À égalité, classement partagé.</p></section>`;}
function rulesForm(){
 const field=(path,label,type='number',options=null)=>{const value=path.split('.').reduce((o,k)=>o[k],draft);return `<label class="rule-field">${label}${type==='boolean'?`<input type="checkbox" data-rule="${path}" ${value?'checked':''}/>`:options?`<select data-rule="${path}">${options.map(([id,text])=>`<option value="${id}" ${id===value?'selected':''}>${esc(text)}</option>`).join('')}</select>`:`<input type="${type}" data-rule="${path}" value="${esc(value)}" ${type==='number'?'step="1"':''}/>`}</label>`;};
 const group=(title,body,open=false)=>`<details ${open?'open':''}><summary>${title}</summary><div class="rule-grid">${body}${title==='Repos, hébergement et nourriture'?field('food.restaurantPrice','Prix du restaurant')+field('food.restaurantEnergy','Énergie du restaurant'):''}</div></details>`;
 let body=group('Journées, déplacements et départ',field('distance','Cases par jour (1 à 5)')+Object.keys(draft.terrain).map(k=>field('terrain.'+k,E.terrains[k].name+' : énergie')).join('')+field('ferryPrice','Prix du bateau (pièces)')+field('startEnergy','Énergie de départ')+field('maxEnergy','Énergie maximale')+field('startMoney','Argent de départ')+field('startFood','Nourriture de départ')+field('salary','Salaire')+field('workDays','Jours consommés par le travail')+field('workCityOnly','Travail uniquement en ville','boolean'),true);
 body+=group('Repos, hébergement et nourriture',Object.entries(draft.rest).map(([id,a])=>`<h4>${a.name}</h4>`+field('rest.'+id+'.price','Prix')+field('rest.'+id+'.energy','Énergie récupérée')+field('rest.'+id+'.days','Jours consommés')+field('rest.'+id+'.tent','Tente obligatoire','boolean')+field('rest.'+id+'.cityOnly','Uniquement en ville','boolean')).join('')+Object.entries({energy:'Énergie par repas',stoveBonus:'Bonus réchaud',price:'Prix nourriture',quantity:'Quantité achetée',maxPerTurn:'Repas maximum par jour',cityOnly:'Achat uniquement en ville'}).map(([k,label])=>field('food.'+k,label,typeof draft.food[k]==='boolean'?'boolean':'number')).join(''));
 body+=group('Vélos et inventaires',Object.entries(draft.bikes).map(([id,b])=>`<h4>${b.name}</h4>`+field('bikes.'+id+'.capacity','Capacité')+field('bikes.'+id+'.mountainDiscount','Réduction montagne / col')+field('bikes.'+id+'.extraDistance','Bonus distance (plafond total : 5)')+field('bikes.'+id+'.extraFood','Nourriture de départ supplémentaire')).join('')+Object.entries(draft.equipment).map(([id,e])=>`<h4>${e.name}</h4>`+field('equipment.'+id+'.price','Prix')+field('equipment.'+id+'.space','Encombrement')+field('equipment.'+id+'.energyBonus','Bonus énergie au repos')+('foodBonus'in e?field('equipment.'+id+'.foodBonus','Provisions offertes à l’achat'):'')).join(''));
 body+=group('Points et victoire',Object.keys(draft.points).map(k=>field('points.'+k,k==='objective'?'Objectif accompli':E.terrains[k].name+' : première visite')).join('')+field('victory.mode','Victoire','text',[['objectives','Objectifs'],['points','Points Aventure'],['turns','Nombre de jours']])+field('victory.points','Points pour gagner')+field('victory.turns','Nombre de jours')+field('victory.allObjectives','Attendre tous les objectifs','boolean'));
 return `<h2>⚙️ Règles — mode Créateur</h2><p>Application immédiate aux prochaines actions de tous les joueurs, sans recommencer. Les ressources déjà détenues sont conservées ; les valeurs de départ concernent les nouvelles parties.</p><div class="profile-bar"><select id="rule-profile" aria-label="Profil de règles"><option value="Classique">Classique</option>${Object.keys(profiles).map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('')}</select>${btn('Charger le profil','loadprofile','light')}</div>${field('name','Nom du profil','text')}${body}<p class="toast" role="alert">${esc(message)}</p><div class="sticky-actions">${btn('Appliquer maintenant','applyrules')}${btn('Enregistrer ce profil','saveprofile','light')}${btn('Fermer','close','light')}</div>`;
}
function prepareDraft(source){draft=clone(source||(m&&screen==='game'?m.rules:setupRules));for(const e of draft.events){e.effect={energy:0,money:0,food:0,points:0,...e.effect};e.cost={energy:0,money:0,food:0,...e.cost};}}
function overlay(){let content='',wide=false;
 if(modal==='rules'){content=rulesForm();wide=true;}
 else if(modal==='settings')content=`<h2>Paramètres</h2><p>Un tour = une journée. Travail, bivouac, camping et hôtel consomment au moins une journée. Maximum : 5 cases par jour.</p>${btn('Modifier les journées et les règles','rules')}<p>Sauvegarde automatique : ${auto?'activée':'désactivée'}.</p>${btn('Activer / désactiver','autosave','light')}${m?btn('Exporter la partie (.json)','export','light'):''}<label class="file-import">Importer une partie <input id="import-save" type="file" accept="application/json,.json"/></label><p class="muted">Stockage dans ce navigateur. Exporte le fichier pour le conserver dans ton dossier sur D: ou sur un autre ordinateur.</p><p role="alert">${esc(message)}</p>${btn('Fermer','close','light')}`;
 else if(modal==='shop'){const p=S.player(m);content=`<h2>Inventaire de ${esc(p.name)}</h2><p>${S.inventorySpace(m)}/${m.rules.bikes[p.bike].capacity} emplacements · achats en ville.</p><div class="shop">${Object.entries(m.rules.equipment).map(([id,e])=>`<button data-buy="${id}" ${p.items.includes(id)||p.money<e.price||S.inventorySpace(m)+e.space>m.rules.bikes[p.bike].capacity||m.board[p.pos].type!=='ville'?'disabled':''}>${esc(e.name)} · ${e.price} pièces · ${e.space} place(s)${p.items.includes(id)?' · acquis':''}</button>${p.items.includes(id)?`<button class="light" data-discard="${id}">Déposer ${esc(e.name)} (sans remboursement)</button>`:''}`).join('')}</div><p role="status">${esc(message)}</p>${btn('Fermer','close','light')}`;}
 else if(modal==='stats'){wide=true;content=`<h2>Équilibrage de la partie</h2><p>${m.stats.turns} tours terminés · ${m.stats.events} événements · ${m.stats.energySpent} énergie dépensée · ${m.stats.moneySpent} pièces dépensées.</p><p>Cartes observées : ${Object.entries(m.stats.categories).map(([k,v])=>k+' '+v).join(' · ')}. Un petit échantillon peut s’écarter des probabilités.</p><div class="table-scroll"><table><thead><tr><th>Joueur</th><th>Déplacements</th><th>Travail</th><th>Repos</th><th>Événements</th><th>Points</th></tr></thead><tbody>${m.players.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.stats.steps}</td><td>${p.stats.work}</td><td>${p.stats.rest}</td><td>${p.stats.events}</td><td>${p.points}</td></tr>`).join('')}</tbody></table></div><details><summary>Historique complet (${m.history.length})</summary><ol class="history">${[...m.history].reverse().map(h=>`<li>Jour ${h.round} · ${esc(h.name)} : ${esc(h.text)}</li>`).join('')}</ol></details>${btn('Exporter la partie et ses statistiques','export','light')}${btn('Fermer','close','light')}`;}
 else if(modal.startsWith('player-')){const p=m.players[+modal.slice(7)];content=`<h2 style="color:${p.color}">${esc(p.name)}</h2><p>${p.energy} énergie · ${p.food} nourriture · ${p.money} pièces · ${p.points} points.</p>${objective(S.view(m,p))}<p>Inventaire : ${p.items.map(i=>esc(m.rules.equipment[i].name)).join(' · ')||'vide'}</p>${btn('Fermer','close','light')}`;}
 else if(modal==='confirm')content=`<h2>Nouvelle partie ?</h2><p>La sauvegarde sera remplacée au début de la nouvelle partie. Tu peux d’abord l’exporter.</p>${btn('Exporter','export','light')}${btn('Choisir le plateau','selectbike')}${btn('Annuler','close','light')}`;
 else if(modal==='finish')content=`<h2>Terminer la partie ?</h2><p>Afficher le classement final et conserver l’historique.</p>${btn('Terminer','finish-confirm')}${btn('Annuler','close','light')}`;
 else if(m?.event&&screen==='game'){const e=m.event,p=S.player(m);content=`<span class="eyebrow">FIN DE JOURNÉE · ${esc(p.name)} · ${e.category==='negative'?'NÉGATIF':e.category==='positive'?'POSITIF':'DÉFI'}</span><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p><p>Effets : ${Object.entries(e.effect).filter(([,v])=>v!==0).map(([k,v])=>(v>0?'+':'')+v+' '+({energy:'énergie',food:'nourriture',money:'pièces',points:'points Aventure'}[k])).join(' · ')||'aucun'}.</p>${e.protect?`<p>Équipement utile : ${esc(m.rules.equipment[e.protect]?.name||e.protect)}${e.consume?' (consommé)':''}.</p>`:''}${e.category==='challenge'?`<p>Coût sans équipement : ${Object.entries(e.cost||{}).filter(([,v])=>v>0).map(([k,v])=>v+' '+k).join(' · ')||'gratuit'}. Aucun dé.</p>${btn('Relever le défi','resolve','',!S.canChallenge(m))}${btn('Refuser le défi','decline','light')}`:btn('Résoudre et passer au joueur suivant →','resolve')}`;}
 else if(m?.done&&screen==='game')content=`<h2>🏆 Partie terminée</h2>${leaderboard()}${btn('Historique et statistiques','stats')}${btn('Retour à l’accueil','home','light')}`;
 if(content&&modal!=='rules')content+=`<p>${btn('⚙️ Modifier les règles','rules','light')}</p>`;
 return content?`<div class="modal-back"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true">${content}</section></div>`:'';
}
function readRoster(){document.querySelectorAll('[data-roster]').forEach(el=>{roster[+el.dataset.roster][el.dataset.field]=el.value;});}
function captureRules(){document.querySelectorAll('[data-rule]').forEach(el=>setPath(draft,el.dataset.rule,el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value));return validateRules(draft);}
function center(){const map=document.querySelector('.map');if(!m||!map)return;const t=m.board[S.player(m).pos];if(m.mode==='plateau'){const world=document.querySelector('.europe-world'),scale=.8*zoom;map.scrollTo({left:Math.max(0,(world?.offsetLeft||0)+t.x*scale-map.clientWidth/2),top:Math.max(0,(world?.offsetTop||0)+t.y*scale-map.clientHeight/2),behavior:'smooth'});}else document.querySelector('[data-token="'+S.player(m).id+'"]')?.closest('.tile')?.scrollIntoView?.({block:'center',inline:'center'});}
function download(){const blob=new Blob([S.serialize(m)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='aventure-velo-jour-'+m.round+'.json';a.click();URL.revokeObjectURL(url);}
function act(a){message='';
 if(a==='new'){if(m&&!m.done)modal='confirm';else screen='modes';}
 else if(a==='selectbike'||a==='modes'){modal='';screen='modes';}
 else if(a==='start'){readRoster();choosing=0;for(const p of roster)p.items=[];screen='equipment';}
 else if(a==='setup'){screen='setup';choosing=0;}
 else if(a==='equipment-next'){choosing++;if(choosing>=roster.length){choosing=0;drawn=drawVoyages();screen='voyages';}}
 else if(a==='continue'){screen='game';modal='';}
 else if(a==='home'){screen='home';modal='';}
 else if(a==='rules'){prepareDraft();modal='rules';}
 else if(['settings','shop','stats','finish'].includes(a))modal=a;
 else if(a==='close')modal='';
 else if(a==='applyrules'||a==='saveprofile'){try{const r=captureRules();if(a==='saveprofile'){let name=r.name.trim();if(!name||name==='Classique')name='Personnalisé';r.name=name;profiles[name]=clone(r);localStorage.setItem('velo-rule-profiles',JSON.stringify(profiles));draft=r;message='Profil « '+name+' » enregistré. Clique sur Appliquer pour modifier la partie.';}else{setupRules=r;if(m&&screen==='game')S.updateRules(m,r);modal='';message='Règles appliquées aux prochaines actions.';}}catch(e){message=e.message;}}
 else if(a==='loadprofile'){const name=document.querySelector('#rule-profile').value;prepareDraft(name==='Classique'?CLASSIC:profiles[name]);}
 else if(a==='autosave'){auto=!auto;localStorage.setItem('velo-auto',auto);}
 else if(a==='save'){message=persist(true)?'Partie sauvegardée sur cet appareil.':message;}
 else if(a==='export'){if(m)download();}
 else if(a==='finish-confirm'){m.done=true;m.phase='finished';modal='';}
 else if(a==='rotate'&&m.phase==='place'){const t=m.hand[selected];if(t)t.rotation=(t.rotation+1)%4;}
 else if(a==='move'){if(!S.move(m,mapSelection))message='Déplacement impossible : énergie, voisins ou limite quotidienne.';else mapSelection='';}
 else if(a==='route-clear'){route=[];mapSelection='';}
 else if(a==='route-go'){const check=S.routeCheck(m,route);if(!check.ok)message=check.reason;else{S.executeRoute(m,route);route=[];mapSelection='';}}
 else if(a==='ferry-confirm'){if(!S.travelFerry(m,ferryTarget))message='Traversée indisponible : port ou argent insuffisant.';else{modal='';route=[];mapSelection='';}}
 else if(a==='ferry-cancel')modal='';
 else if(a==='repair'){if(!S.repairPuncture(m))message='Réparation indisponible.';}
 else if(a==='cards')modal='cards';
 else if(a==='choose-0'||a==='choose-1'){S.chooseCard(m,Number(a.slice(-1)));modal='';route=[];}
 else if(a.startsWith('card-')){cardIndex=Number(a.slice(5));const card=cardById(S.player(m).cardHand[cardIndex]);if(card?.choice==='food-energy')modal='card-effect-choice';else if(card?.target==='self'){if(S.playCard(m,cardIndex,S.player(m).id))modal='';}else modal='card-target';}
 else if(a==='ravito-food'||a==='ravito-energy'){if(S.playCard(m,cardIndex,S.player(m).id,a==='ravito-food'?'food':'energy'))modal='';}
 else if(a.startsWith('target-')){if(!S.playCard(m,cardIndex,a.slice(7)))message='Cette carte ne peut pas être jouée sur cette cible.';else modal='';}
 else if(a.startsWith('pending-')){const choice={ 'pending-tube':'tube','pending-lose':'lose','pending-kit':'kit','pending-energy':'energy','pending-food':'food','pending-auto':'auto'}[a];if(!S.resolvePendingCard(m,choice))message='Cette résolution n’est pas disponible.';}
 else if(a==='eat'){if(!S.eat(m))message='Repas indisponible.';}
 else if(a==='food'){if(!S.buyFood(m))message='Achat indisponible.';}
 else if(a==='restaurant'){if(!S.restaurant(m))message='Restaurant indisponible : ville, argent ou repas quotidien.';}
 else if(a==='work'){if(!S.work(m))message='Le travail demande une journée sans déplacement ni pose de tuile.';mapSelection='';}
 else if(a.startsWith('rest-')){if(!S.rest(m,a.slice(5)))message='Repos indisponible : journée commencée, argent, lieu ou équipement requis.';mapSelection='';}
 else if(a==='endturn'){S.endTurn(m);mapSelection='';route=[];}
 else if(a==='resolve'||a==='decline'){S.resolve(m,a==='decline'?'decline':'accept');mapSelection='';}
 else if(a==='zoomin')zoom=Math.min(2,zoom+.2);
 else if(a==='zoomout')zoom=Math.max(.6,zoom-.2);
 render();if(['continue','center','zoomin','zoomout','resolve','decline','work','rest-bivouac','rest-camping','rest-hotel'].includes(a))center();
}
function bind(){
 document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>act(el.dataset.action));
 document.querySelectorAll('[data-mode]').forEach(el=>el.onclick=()=>{mode=el.dataset.mode;screen='setup';render();});
 const count=document.querySelector('#player-count');if(count)count.onchange=()=>{readRoster();const n=+count.value;roster=Array.from({length:n},(_,i)=>roster[i]||{name:'Joueur '+(i+1),bike:'gravel'});render();};
 document.querySelectorAll('[data-voyage]').forEach(el=>el.onclick=()=>{const id=el.dataset.voyage;if(!drawn.some(v=>v.id===id))return;roster[choosing].voyage=id;choosing++;if(choosing<roster.length)drawn=drawVoyages();else{m=S.createMatch(roster,mode,setupRules);screen='game';zoom=1;mapSelection='';selected=0;}render();if(screen==='game')center();});
 document.querySelectorAll('[data-select]').forEach(el=>el.onclick=()=>{selected=+el.dataset.select;render();});
 document.querySelectorAll('[data-place]').forEach(el=>el.onclick=()=>{const [x,y]=el.dataset.place.split(',').map(Number);S.place(m,selected,x,y);selected=0;render();});
 document.querySelectorAll('[data-move]').forEach(el=>{el.onclick=()=>{const key=el.dataset.move;if(m?.phase==='move'){if(m.mode==='plateau'&&S.ferryOptions(m).some(t=>t.key===key)&&!route.length){ferryTarget=key;modal='ferry';}else if(route.at(-1)===key){route.pop();mapSelection=route.at(-1)||'';}else{const candidate=[...route,key],check=S.routeCheck(m,candidate);if(check.ok){route=candidate;mapSelection=key;}else{mapSelection=key;message=check.reason;}}}else mapSelection=key;render();};el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();el.onclick();}};});
 document.querySelectorAll('[data-equipment]').forEach(el=>el.onclick=()=>{const id=el.dataset.equipment,p=roster[choosing];p.items||=[];p.items=p.items.includes(id)?p.items.filter(i=>i!==id):[...p.items,id];render();});
 document.querySelectorAll('[data-buy]').forEach(el=>el.onclick=()=>{if(!S.buy(m,el.dataset.buy))message='Achat impossible : lieu, argent ou capacité.';render();});
 document.querySelectorAll('[data-discard]').forEach(el=>el.onclick=()=>{S.discard(m,el.dataset.discard);render();});
 document.querySelectorAll('[data-player]').forEach(el=>el.onclick=()=>{modal='player-'+el.dataset.player;render();});
 const file=document.querySelector('#import-save');if(file)file.onchange=async()=>{try{const imported=S.load(await file.files[0].text());if(m)localStorage.setItem('velo-save-before-import',S.serialize(m));m=imported;screen='game';modal='';mapSelection='';persist(true);render();center();}catch(e){message='Import refusé : '+e.message;render();}};
}
const previousGame=game,previousOverlay=overlay;
game=()=>{
 if(m.mode==='tuiles')return previousGame();
 const p=S.player(m),g=S.view(m),reachable=S.moves(m),r=m.rules,scale=.9*zoom;
 return `<main class="game"><div class="player-order">${m.players.map((q,i)=>`<button data-player="${i}" class="${i===m.activeIndex?'active':''}" style="--player-color:${q.color}"><span>●</span> ${esc(q.name)} · ${q.points} ✨ <small>Jour ${q.availableDay}${i===m.activeIndex?' · à jouer':''}</small></button>`).join('')}</div><div class="topbar"><div><span class="eyebrow">NOUVEAU PLATEAU EUROPE · JOUR ${m.round}</span><h2>${esc(p.name)} <small class="muted">${m.moved}/${S.distance(m)} cases aujourd’hui</small></h2></div><div class="stats">${[['⚡','Énergie',p.energy+'/'+r.maxEnergy],['🍎','Nourriture',p.food],['🪙','Argent',p.money],['✨','Aventure',p.points]].map(([i,n,v])=>`<div class="stat">${i} ${n}<strong>${v}</strong></div>`).join('')}</div></div><div class="hint">${m.phase==='card-choice'?'Choisis une carte à garder pour terminer ton tour.':m.phase==='card-resolution'?'Une carte négative doit être résolue avant de commencer ta journée.':m.phase==='puncture'?'Crevaison ! Répare ou retourne à la dernière ville.':'Clique successivement sur 1 à '+Math.max(0,S.distance(m)-m.moved)+' cases voisines, puis effectue le parcours. Les bateaux se prennent séparément.'}</div>${objective(g)}<div class="layout"><section><div class="map-wrap"><div class="map"><div class="europe-world" style="width:${MAP_WIDTH*scale}px;height:${MAP_HEIGHT*scale}px">${playableMap(g,reachable,(_,t)=>S.cost(m,t),mapSelection,route)}</div></div><div class="maptools">${btn('−','zoomout')}${btn('+','zoomin')}${btn('◎','center')}</div></div>${details(reachable)}<div class="board-legend">${['plaine','moyenne_montagne','montagne','cote','ville'].map(id=>`<span>${E.terrains[id].icon} ${E.terrains[id].name} : ${r.terrain[id]} ⚡</span>`).join('')}</div><div class="toast" role="status">${esc(message)}</div>${leaderboard()}</section>${sidebar()}</div></main>`;
};
details=reachable=>{const t=m.board[mapSelection],check=S.routeCheck(m,route),ferries=S.ferryOptions(m),picked=route.map((k,i)=>`${i+1}. ${m.board[k].name||E.terrains[m.board[k].type].name}`).join(' → ');return `<div class="cell-details route-planner"><div><strong>${t?esc(t.name||E.terrains[t.type].name):'Planifier l’étape'}</strong><small>${route.length?esc(picked)+' · −'+(check.energyUsed||0)+' énergie':'Sélectionne des cases voisines sur la carte.'}</small>${ferries.length?`<small>⛴ Depuis ce port : ${ferries.map(f=>esc(f.name||f.key)).join(', ')} · ${m.rules.ferryPrice} pièces, fin de journée.</small>`:''}</div><div class="route-buttons">${btn('Effacer','route-clear','light',!route.length)}${btn('🚴 Effectuer le parcours','route-go','',!check.ok)}</div></div>`;};
sidebar=()=>{const p=S.player(m),r=m.rules,blocked=m.done||!['move','place'].includes(m.phase),dayBlocked=blocked||m.moved>0||m.placed,city=m.board[p.pos].type==='ville',canEat=p.items.includes('rechaud')||city||m.board[p.pos].type==='auberge';return `<aside class="panel"><h3>La journée de ${esc(p.name)}</h3><p>${esc(r.bikes[p.bike].name)} · ${S.inventorySpace(m)}/${r.bikes[p.bike].capacity} emplacements</p><div class="actions">${btn('🃏 Cartes de jeu ('+p.cardHand.length+')','cards','',blocked)}${btn('🍎 Manger · +'+(r.food.energy+(p.items.includes('rechaud')?r.food.stoveBonus:0))+' énergie','eat','',blocked||!canEat||!p.food||m.ate>=r.food.maxPerTurn||p.energy>=r.maxEnergy)}${btn('🥕 Acheter '+r.food.quantity+' provisions · '+r.food.price+' pièces','food','',blocked||p.money<r.food.price||(r.food.cityOnly&&!city))}${btn('🍽 Restaurant · '+r.food.restaurantPrice+' pièces','restaurant','',blocked||!city||p.money<r.food.restaurantPrice||p.energy>=r.maxEnergy)}${btn('🔧 Travailler · +'+r.salary+' pièces','work','',dayBlocked||(r.workCityOnly&&!city))}${Object.entries(r.rest).map(([id,a])=>{const free=id==='bivouac'&&p.turnModifiers?.freeBivouac;return btn(`${id==='bivouac'?'⛺':id==='camping'?'🏕':'🏨'} ${a.name} · ${free?'gratuit':a.price+' pièces'} · ${a.days} jour(s)`,'rest-'+id,'',dayBlocked||(!free&&(p.money<a.price||(a.tent&&!p.items.includes('tente'))))||(a.cityOnly&&!city));}).join('')}${S.ferryOptions(m).map(t=>`<button data-ferry="${esc(t.key)}" ${p.money<r.ferryPrice?'disabled':''}>⛴ Bateau vers ${esc(t.name||t.key)} · ${r.ferryPrice} pièces</button>`).join('')}${btn('🎒 Équipements','shop','',blocked)}${btn('Terminer ma journée →','endturn','',blocked)}${btn('Sauvegarder','save','light')}${btn('Historique et statistiques','stats','light')}${btn('Terminer la partie','finish','light')}</div><p class="muted">Sans réchaud, un repas n’est possible qu’en ville ou à l’auberge. Le bivouac exige normalement une tente ; Abri trouvé l’offre une fois.</p><h4>Inventaire</h4><p>${p.items.map(i=>esc(r.equipment[i].name)).join(' · ')||'Aucun équipement'}</p><h4>Journal</h4><div class="log">${p.log.map(l=>`<div>• ${esc(l)}</div>`).join('')}</div></aside>`;};
overlay=()=>{let content='';if(!modal&&m&&screen==='game'&&m.phase==='card-choice')content=`<span class="eyebrow">FIN DE JOURNÉE · ${esc(S.player(m).name)}</span><h2>Pioche deux cartes, garde-en une</h2><div class="card-choice-list">${m.cardChoices.map((id,i)=>{const c=cardById(id);return `<article class="${c.type}"><div class="card-title"><span>${c.icon||'🃏'}</span><div><small>${c.type==='negative'?'À donner':'Positive'}</small><h3>${esc(c.title)}</h3></div></div><p>${esc(c.text)}</p>${btn('Garder cette carte','choose-'+i)}</article>`;}).join('')}</div><p>L’autre carte est défaussée. Ton tour se termine après ton choix.</p>`;
 else if(!modal&&m&&screen==='game'&&m.phase==='card-resolution'){const p=S.player(m),c=cardById(p.pendingCards[0]);let choices='';if(c?.resolution==='tube')choices=(p.items.includes('chambre')?btn('Utiliser ma chambre à air','pending-tube'):'')+btn('Perdre 1 déplacement','pending-lose','light');else if(c?.resolution==='kit-energy')choices=(p.items.includes('kit')?btn('Utiliser mon kit (sans le consommer)','pending-kit'):'')+btn('Perdre 2 énergie','pending-energy','light');else if(c?.resolution==='hunger')choices=(p.food?btn('Dépenser 1 nourriture','pending-food'):'')+btn('Perdre 2 énergie','pending-energy','light');else choices=btn('Résoudre','pending-auto');content=`<span class="eyebrow">CARTE À RÉSOUDRE · DÉBUT DE JOURNÉE</span><h2>${c?.icon||'🃏'} ${esc(c?.title||'Carte')}</h2><p>${esc(c?.text||'')}</p><div class="card-resolution-choices">${choices}</div>`;}
 else if(!modal&&m&&screen==='game'&&m.phase==='puncture')content=`<h2>🚲 Crevaison</h2><p>${S.player(m).items.includes('kit')?'Ton kit de réparation te permet de reprendre ta journée.':'Sans kit de réparation, tu retournes à la dernière ville visitée et tu perds cette journée.'}</p>${btn(S.player(m).items.includes('kit')?'Réparer et continuer':'Retourner à la ville','repair')}`;
 else if(modal==='cards'){const p=S.player(m);content=`<h2>🃏 Cartes de jeu de ${esc(p.name)}</h2><p>Les positives se jouent pendant ton tour. Une carte négative se donne à un adversaire et sera résolue au début de son prochain tour.</p><div class="card-choice-list">${p.cardHand.map((id,i)=>{const c=cardById(id);return `<article class="game-card ${c.type||'positive'}"><div class="card-title"><span>${c.icon||'🃏'}</span><div><small>${c.type==='negative'?'Négative · à donner':'Positive · pour toi'}</small><h3>${esc(c.title)}</h3></div></div><p>${esc(c.text)}</p>${btn(c.target==='other'?'Donner à un adversaire':'Jouer','card-'+i,'',c.target==='other'&&m.players.length<2||!S.canPlayCard(m,i))}</article>`;}).join('')||'<p>Aucune carte en main.</p>'}</div>${btn('Fermer','close','light')}`;}
 else if(modal==='card-effect-choice'){const c=cardById(S.player(m).cardHand[cardIndex]);content=`<h2>${c?.icon||'🍎'} ${esc(c?.title||'Bon ravito')}</h2><p>Choisis ton ravitaillement.</p>${btn('+1 nourriture','ravito-food')}${btn('+1 énergie','ravito-energy','',S.player(m).energy>=m.rules.maxEnergy)}${btn('Annuler','cards','light')}`;}
 else if(modal==='card-target'){const c=cardById(S.player(m).cardHand[cardIndex]);content=`<h2>${esc(c.title)} : choisir la cible</h2><p>${esc(c.text)}</p>${m.players.filter(p=>p.id!==S.player(m).id).map(p=>btn(esc(p.name),'target-'+p.id,'',c.id==='crevaison'&&p.flat)).join('')}${btn('Annuler','cards','light')}`;}
 else if(modal==='ferry'){const t=m.board[ferryTarget];content=`<h2>⛴ Traversée vers ${esc(t?.name||'le port')}</h2><p>Coût : ${m.rules.ferryPrice} pièces. Tu débarques sur la case de destination et ta journée se termine. Tu pioches ensuite deux cartes et en gardes une.</p>${btn('Confirmer la traversée','ferry-confirm','',S.player(m).money<m.rules.ferryPrice)}${btn('Annuler','ferry-cancel','light')}`;}
 if(!content)return previousOverlay();return `<div class="modal-back"><section class="modal" role="dialog" aria-modal="true">${content}</section></div>`;};
const previousBind=bind;bind=()=>{previousBind();document.querySelectorAll('[data-ferry]').forEach(el=>el.onclick=()=>{ferryTarget=el.dataset.ferry;modal='ferry';render();});};
render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
